// Managed WireGuard VPN on the device. Every key here is generated by the test run; none is committed.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { generateKeyPairSync, sign } from 'node:crypto';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { Agent, type Host } from '../src/agent.ts';
import { ApiError, type DeviceApi } from '../src/api.ts';
import { canonical } from '../src/commands.ts';
import { StateFile, type Policy } from '../src/state.ts';
import {
  isWgKey, parseNmConnections, renderKillSwitch, renderNmConnection, rotationDue, userVpnsToRemove, vpnPlan, wgKeyPair, wgPublicKey,
  VPN_CONNECTION_UUID, type NmConnection, type VpnConfig, type VpnPlan,
} from '../src/vpn.ts';

const server = generateKeyPairSync('ed25519');
const attacker = generateKeyPairSync('ed25519');
const DAY = 86_400_000;
const GATEWAY = wgKeyPair().publicKey;

const signed = <T extends Record<string, unknown>>(body: T, key = server.privateKey) =>
  ({ ...body, signature: `k1:${sign(null, Buffer.from(canonical(body)), key).toString('base64')}` }) as unknown as T & { signature: string };

function config(devicePub: string, over: Partial<VpnConfig> = {}): Omit<VpnConfig, 'signature'> {
  return {
    device_id: 'dev-1', enabled: true, version: '3', issued_at: '2026-10-15T10:00:00Z', device_public_key: devicePub,
    interface: { address: ['10.70.0.2/32'], dns: ['10.70.0.1'], dns_search: ['corp.example'], mtu: 1420 },
    peer: { public_key: GATEWAY, endpoint: 'vpn.example.com:51820', allowed_ips: ['0.0.0.0/0'], persistent_keepalive: 25 },
    always_on: false, kill_switch: false, ...over,
  };
}

test('keys: WireGuard base64 form, public derived from private like `wg pubkey`', () => {
  const k = wgKeyPair();
  assert.ok(isWgKey(k.privateKey) && isWgKey(k.publicKey));
  assert.equal(Buffer.from(k.privateKey, 'base64').length, 32);
  assert.equal(wgPublicKey(k.privateKey), k.publicKey);
  assert.notEqual(wgKeyPair().privateKey, k.privateKey);
  assert.equal(isWgKey('abc='), false);
  assert.throws(() => wgPublicKey('nope'), /BAD_WG_KEY/);
});

test('plan: always-on from the config or from policy vpn_required; disabled config = nothing', () => {
  const pub = wgKeyPair().publicKey;
  const c = signed(config(pub)) as VpnConfig;
  assert.equal(vpnPlan(c, null)!.autoconnect, false);
  assert.equal(vpnPlan(c, { version: '1', signature: '', vpn_required: true })!.autoconnect, true);
  assert.equal(vpnPlan(signed(config(pub, { always_on: true })) as VpnConfig, null)!.autoconnect, true);
  assert.deepEqual(vpnPlan(c, null)!.endpoint, { host: 'vpn.example.com', port: 51820 });
  assert.deepEqual(vpnPlan(signed(config(pub, { peer: { ...(config(pub).peer as NonNullable<VpnConfig['peer']>), endpoint: '[2001:db8::1]:443' } })) as VpnConfig, null)!.endpoint, { host: '2001:db8::1', port: 443 });
  assert.equal(vpnPlan({ ...c, enabled: false }, null), null);
  assert.equal(vpnPlan(null, { version: '1', signature: '', vpn_required: true }), null);
  // Values that would end up in a root-owned keyfile are checked even after the signature.
  assert.throws(() => vpnPlan({ ...c, peer: { ...c.peer!, endpoint: 'evil\n[connection]:1' } }, null), /VPN_CONFIG_INVALID/);
  assert.throws(() => vpnPlan({ ...c, interface: { ...c.interface!, dns: ['1.1.1.1\nx=y'] } }, null), /VPN_CONFIG_INVALID/);
  assert.throws(() => vpnPlan({ ...c, peer: { ...c.peer!, public_key: 'x' } }, null), /VPN_CONFIG_INVALID/);
});

test('NetworkManager keyfile: wireguard connection with the device key, peer, routes and exclusive DNS', () => {
  const k = wgKeyPair();
  const plan = vpnPlan(signed(config(k.publicKey, { always_on: true })) as VpnConfig, null)!;
  const f = renderNmConnection(plan, k.privateKey);
  for (const line of [
    'type=wireguard', `uuid=${VPN_CONNECTION_UUID}`, 'interface-name=wsvpn0', 'autoconnect=true', 'autoconnect-retries=0',
    `private-key=${k.privateKey}`, 'private-key-flags=0', 'mtu=1420',
    `[wireguard-peer.${GATEWAY}]`, 'endpoint=vpn.example.com:51820', 'allowed-ips=0.0.0.0/0;', 'persistent-keepalive=25',
    'method=manual', 'address1=10.70.0.2/32', 'dns=10.70.0.1;', 'dns-search=corp.example;', 'dns-priority=-50',
  ]) assert.ok(f.split('\n').includes(line), `missing ${line}\n${f}`);
  assert.match(f, /\[ipv6\]\naddr-gen-mode=default\nmethod=disabled/);
  // Split tunnel, not always-on: no autoconnect and no exclusive DNS.
  const split = renderNmConnection(vpnPlan(signed(config(k.publicKey, { peer: { ...(config(k.publicKey).peer as NonNullable<VpnConfig['peer']>), allowed_ips: ['10.0.0.0/8', 'fd00::/8'] } })) as VpnConfig, null)!, k.privateKey);
  assert.match(split, /autoconnect=false/);
  assert.match(split, /allowed-ips=10\.0\.0\.0\/8;fd00::\/8;/);
  assert.doesNotMatch(split, /dns-priority/);
  assert.throws(() => renderNmConnection(plan, 'not a key'), /BAD_WG_KEY/);
});

test('kill switch: drop by default, allow tunnel, endpoint handshake, loopback, DHCP and neighbour discovery', () => {
  const r = renderKillSwitch(['203.0.113.7', '2001:db8::7'], 51820);
  assert.match(r, /type filter hook output priority filter; policy drop;/);
  assert.match(r, /oifname "wsvpn0" accept/);
  assert.match(r, /oifname "lo" accept/);
  assert.match(r, /ip daddr \{ 203\.0\.113\.7 \} udp dport 51820 accept/);
  assert.match(r, /ip6 daddr \{ 2001:db8::7 \} udp dport 51820 accept/);
  assert.match(r, /udp sport 68 udp dport 67 accept/);
  assert.match(r, /^delete table inet worksuite_vpn_killswitch$/m);   // atomic replace under nft -f
  assert.doesNotMatch(r, /dport 53/);                                  // no DNS outside the tunnel
  assert.throws(() => renderKillSwitch([], 51820), /NO_ENDPOINT_ADDRESS/);
  assert.throws(() => renderKillSwitch(['1.2.3.4; flush ruleset'], 51820), /BAD_ENDPOINT_ADDRESS/);
  assert.throws(() => renderKillSwitch(['1.2.3.4'], 0), /BAD_PORT/);
});

test('user VPN policy: block removes every VPN profile except the managed one', () => {
  const conns = parseNmConnections([
    'Office Wi-Fi:11111111-1111-1111-1111-111111111111:802-11-wireless:yes',
    `WorkSuite VPN:${VPN_CONNECTION_UUID}:wireguard:yes`,
    'home\\:wg:22222222-2222-2222-2222-222222222222:wireguard:no',
    'OpenVPN:33333333-3333-3333-3333-333333333333:vpn:no',
  ].join('\n'));
  assert.deepEqual(conns.map((c) => c.name), ['WorkSuite VPN', 'home:wg', 'OpenVPN']);
  assert.deepEqual(userVpnsToRemove(conns, { version: '1', signature: '', user_vpn: 'block' }).map((c) => c.name), ['home:wg', 'OpenVPN']);
  assert.deepEqual(userVpnsToRemove(conns, { version: '1', signature: '', user_vpn: 'allow' }), []);
  assert.deepEqual(userVpnsToRemove(conns, null), []);
});

test('rotation is due after key_rotation_days', () => {
  const c = config('x', { key_rotation_days: 30 }) as VpnConfig;
  assert.equal(rotationDue(c, 0 + 1, 31 * DAY), true);
  assert.equal(rotationDue(c, 10 * DAY, 31 * DAY), false);
  assert.equal(rotationDue({ ...c, key_rotation_days: undefined }, 1, 999 * DAY), false);
});

// ---- agent flow with a fake server and host ----
function world(opts: { orgVpn?: Partial<VpnConfig> | false; policy?: Omit<Policy, 'signature'>; ignoreRegisterKey?: boolean } = {}) {
  const dir = mkdtempSync(join(tmpdir(), 'ws-vpn-'));
  let now = Date.parse('2026-10-15T10:00:00Z');
  const s = {
    peerKey: undefined as string | undefined, sentBodies: [] as unknown[], applied: [] as (VpnPlan | null)[], removed: [] as string[],
    keys: [] as { privateKey: string; publicKey: string }[], forgotten: 0, forge: false, otherDevice: false,
    conns: [] as NmConnection[], policy: signed({ version: 'p1', ...(opts.policy ?? {}) }) as Policy,
  };
  const current = () => s.keys[s.keys.length - 1];
  const vpnFor = () => {
    if (opts.orgVpn === false) return signed({ device_id: 'dev-1', enabled: false, version: '0', issued_at: 'x' });
    if (!s.peerKey) throw new ApiError(409, 'VPN_PEER_KEY_REQUIRED');
    return signed({ ...config(s.peerKey, opts.orgVpn || {}), ...(s.otherDevice ? { device_id: 'dev-2' } : {}) }, s.forge ? attacker.privateKey : server.privateKey);
  };
  const api: DeviceApi = {
    async register(_u, _t, body) { s.sentBodies.push(body); s.peerKey = opts.ignoreRegisterKey ? undefined : body.wg_public_key; return { device_id: 'dev-1', credential: 'c', org_name: 'Org' }; },
    async heartbeat() { return { commands: [] }; },
    async policy() { return s.policy; },
    async ack() {}, async inventory() {}, async diagnostics() {}, async audit() {},
    async vpn() { return vpnFor() as VpnConfig; },
    async vpnPeer(pub) { s.sentBodies.push({ public_key: pub }); s.peerKey = pub; return vpnFor() as VpnConfig; },
    async remoteSupportCommands() { return { commands: [] }; },
    async remoteSupportState() {},
  };
  const host: Host = {
    async generateDeviceKey() { return { publicKeyPem: 'PEM', tpmBacked: false }; },
    async facts() { return { arch: 'amd64', hostname: 'h', os_version: '1', shell_version: '1', kernel_version: '6', update_status: 'idle' }; },
    async inventory() { return {}; },
    publishCredential() {}, publishPolicy() {}, publishStatus() {},
    async lockAllSessions() {}, async applyEnforcement() {}, setOfflineAccessBlock() {},
    async installApproved() {}, async removeApplication() {}, async scheduleUpdate() {}, async scheduleReboot() {},
    async collectDiagnostics(p) { return { profile: p, sha256: '', content: '' }; },
    async isFullyEncrypted() { return true; },
    async wipeWorkSuiteData() {}, async cryptoErase() {}, audit() {},
    async wgPublicKey(rotate) { if (rotate || !current()) s.keys.push(wgKeyPair()); return current().publicKey; },
    forgetWgKey() { s.forgotten++; },
    async applyVpn(plan) { if (plan) renderNmConnection(plan, current().privateKey); s.applied.push(plan); },
    async vpnConnections() { return s.conns; },
    async removeConnection(uuid) { s.removed.push(uuid); s.conns = s.conns.filter((c) => c.uuid !== uuid); },
  };
  const agent = new Agent({ state: new StateFile(join(dir, 'state.json')), api, host, keys: (id) => (id === 'k1' ? server.publicKey : undefined), now: () => now });
  return { agent, s, current, tick: (ms: number) => { now += ms; }, cleanup: () => rmSync(dir, { recursive: true, force: true }) };
}

test('enrolment sends only the WireGuard public key; the verified config is applied', async () => {
  const w = world({ orgVpn: { always_on: true, kill_switch: true } });
  await w.agent.enroll('https://ws.example', 'tok');
  const body = w.s.sentBodies[0] as Record<string, unknown>;
  assert.equal(body.wg_public_key, w.current().publicKey);
  assert.ok(!JSON.stringify(w.s.sentBodies).includes(w.current().privateKey), 'private key never sent');
  const plan = w.s.applied.at(-1)!;
  assert.equal(plan.config.device_public_key, w.current().publicKey);
  assert.equal(plan.autoconnect, true);
  assert.equal(plan.kill_switch, true);
  assert.equal((w.agent.status().vpn as { always_on: boolean }).always_on, true);
  w.cleanup();
});

test('first enrolment uses one keypair, even if the server ignored the key sent at registration', async () => {
  for (const ignoreRegisterKey of [false, true]) {
    const w = world({ ignoreRegisterKey });
    await w.agent.enroll('https://ws.example', 'tok');
    assert.equal(w.s.keys.length, 1, `ignoreRegisterKey=${ignoreRegisterKey}`);
    assert.equal(w.s.peerKey, w.s.keys[0].publicKey);
    assert.equal(w.s.applied.at(-1)!.config.device_public_key, w.s.keys[0].publicKey);
    w.cleanup();
  }
});

test('no key on the server (or an admin rotation) → new keypair, public half registered', async () => {
  const w = world();
  await w.agent.enroll('https://ws.example', 'tok');
  const first = w.current().publicKey;
  w.s.peerKey = undefined;                       // admin rotated: server forgot the key
  await w.agent.refreshPolicy();
  assert.notEqual(w.current().publicKey, first);
  assert.equal(w.s.peerKey, w.current().publicKey);
  assert.equal(w.s.applied.at(-1)!.config.device_public_key, w.current().publicKey);
  w.cleanup();
});

test('scheduled rotation after key_rotation_days', async () => {
  const w = world({ orgVpn: { key_rotation_days: 30 } });
  await w.agent.enroll('https://ws.example', 'tok');
  const first = w.current().publicKey;
  w.tick(10 * DAY); await w.agent.refreshPolicy();
  assert.equal(w.current().publicKey, first);
  w.tick(21 * DAY); await w.agent.refreshPolicy();
  assert.notEqual(w.current().publicKey, first);
  assert.equal(w.s.applied.at(-1)!.config.device_public_key, w.current().publicKey);
  w.cleanup();
});

test('forged or foreign configs are rejected and the last good one stays', async () => {
  const w = world();
  await w.agent.enroll('https://ws.example', 'tok');
  const good = w.s.applied.at(-1)!;
  assert.ok(good);
  w.s.forge = true;
  await w.agent.refreshPolicy();
  assert.equal(w.s.applied.at(-1)!.config.signature, good.config.signature);
  w.s.forge = false; w.s.otherDevice = true;
  await w.agent.refreshPolicy();
  assert.equal(w.s.applied.at(-1)!.config.device_id, 'dev-1');
  w.cleanup();
});

test('org without a VPN, policy vpn_required, user_vpn=block', async () => {
  const w = world({ orgVpn: false, policy: { user_vpn: 'block', vpn_required: true } });
  w.s.conns = [{ name: 'home', uuid: '22222222-2222-2222-2222-222222222222', type: 'wireguard', active: true }];
  await w.agent.enroll('https://ws.example', 'tok');
  assert.equal(w.s.applied.at(-1), null);
  assert.deepEqual(w.s.removed, ['22222222-2222-2222-2222-222222222222']);
  assert.equal(w.agent.status().user_vpn_allowed, false);
  w.cleanup();
});

test('policy vpn_required forces autoconnect even when the config is not always-on', async () => {
  const w = world({ policy: { vpn_required: true } });
  await w.agent.enroll('https://ws.example', 'tok');
  assert.equal(w.s.applied.at(-1)!.autoconnect, true);
  w.cleanup();
});

test('revocation removes the connection and forgets the key', async () => {
  const w = world({ orgVpn: { always_on: true } });
  await w.agent.enroll('https://ws.example', 'tok');
  assert.ok(w.s.applied.at(-1));
  (w.agent as unknown as { o: { api: DeviceApi } }).o.api.heartbeat = async () => { throw new ApiError(403, 'DEVICE_REVOKED'); };
  await w.agent.checkIn();
  await new Promise((r) => setTimeout(r, 10));
  assert.equal(w.s.applied.at(-1), null);
  assert.equal(w.s.forgotten, 1);
  assert.equal(w.agent.status().vpn, null);
  w.cleanup();
});
